using System.Text.Json;
namespace StarlightSyndicateDemo;
public static class MutationTestsQ {
 public static void Run(Action<bool,string> check){var w=new DemoWorld();w.NewGame(0);w.WalletFunds=100000;bool found=false;
  var families=new (string Kind,string[] Ids)[]{("weapon",WeaponCatalog.All.Select(d=>d.Id).ToArray()),("defense",DefenseCatalog.All.Select(d=>d.Id).ToArray()),("ewar",EwarCatalog.All.Select(d=>d.Id).ToArray()),("support",SupportCatalog.All.Select(d=>d.Id).ToArray()),("utility",UtilityCatalog.All.Select(d=>d.Id).ToArray()),("mobility",MobilityCatalog.All.Select(d=>d.Id).ToArray()),("enhancement",EnhancementCatalog.All.Select(d=>d.Id).ToArray())};
  foreach(var family in families){var state=w.MutableModulesQ().First(m=>m.Kind==family.Kind&&m.Slot==0).State;var type=state.GetType();foreach(var id in family.Ids){int source=UnifiedCatalog40.FindSourceId(id)??0;if(source==0)continue;type.GetProperty("ModuleId")!.SetValue(state,id);type.GetProperty("Active")?.SetValue(state,false);type.GetProperty("Online")?.SetValue(state,false);var raw=type.GetProperty("Definition")!.GetValue(state);if(raw==null)continue;var profile=CatalogQ.Data.Mutators.FirstOrDefault(m=>m.Mappings.Any(map=>map.Inputs.Contains(source))&&m.Attributes.All(a=>MutationRulesQ.Field(a.Name,raw) is {} field&&raw.GetType().GetProperty(field)?.PropertyType is {} t&&(t==typeof(float)||t==typeof(double)||t==typeof(decimal))));if(profile==null)continue;
    string input=CatalogQ.Item(profile.Type);w.Hangar[input]=1;string before=JsonSerializer.Serialize(raw,raw.GetType());string error=w.MutateModuleQ(family.Kind,0,profile.Type);check(error=="","Eligible source mutation executes / "+id);var mutation=(MutationInstanceQ)type.GetProperty("MutationQ")!.GetValue(state)!;check(w.Hangar[input]==0&&mutation.Factors.All(f=>profile.Attributes.Any(a=>a.Name==f.Key&&f.Value>=a.Min&&f.Value<=a.Max)),"Mutator consumption and sealed source ranges");var changed=type.GetProperty("Definition")!.GetValue(state)!;check(!ReferenceEquals(raw,changed)&&JsonSerializer.Serialize(raw,raw.GetType())==before,"Instance mutation leaves global definition unchanged");check(mutation.Fields.All(f=>Math.Abs(Convert.ToDouble(changed.GetType().GetProperty(f.Key)!.GetValue(changed))-Convert.ToDouble(raw.GetType().GetProperty(f.Key)!.GetValue(raw))*f.Value)<.01),"Live mutated attributes follow stored factors");w.Hangar[input]=1;check(w.MutateModuleQ(family.Kind,0,profile.Type)!=""&&w.Hangar[input]==1,"Repeat mutation denied without consumption");var json=JsonSerializer.Serialize(state,type);var restored=JsonSerializer.Deserialize(json,type)!;var restoredDefinition=type.GetProperty("Definition")!.GetValue(restored)!;check(JsonSerializer.Serialize(changed,changed.GetType())==JsonSerializer.Serialize(restoredDefinition,restoredDefinition.GetType()),"Serialized module retains exact rolled attributes");found=true;break;
   }if(found)break;}
  check(found,"At least one promoted live mutation lifecycle verified");
  var cargoWorld=new DemoWorld();cargoWorld.NewGame(0);var ship=new ParkedShip{System="cargo"};var asset=new UniqueAssetD{Id=ship.Id,Item=ship.Ship.CombatHull,Bank="fleet-q",Json=JsonSerializer.Serialize(ship,WeaponCatalog.JsonOptions)};cargoWorld.CargoItems[asset.Item]=1;check(cargoWorld.RestoreInstanceD(asset,false,"")&&cargoWorld.SystemsQ.RecoveredShips.Count==1,"Physical fitted hull recovery preserves instance in cargo");check(cargoWorld.RecoverCargoShipQ(ship.Id)==""&&cargoWorld.CargoItems[asset.Item]==0&&cargoWorld.ParkedShips.Any(s=>s.Id==ship.Id),"Dock transfer conserves fitted hull and cargo stack");check(cargoWorld.RecoverCargoShipQ(ship.Id)!="","Recovered fitted hull cannot be delivered twice");
 }
}
